'use strict';
// La elección de invitado y la aceptación solo viven en memoria.
const CyberEntry=(()=>{
 let allowed=false,guest=false,accepted=false,mode='login',loading=true,restoring=true,authBusy=false;
 function terms(){return `<dialog id="terms-dialog" aria-labelledby="terms-title"><form method="dialog"><button class="terms-close" aria-label="Cerrar términos">×</button></form><span class="eyebrow">CYBERCRIPT · VERSIÓN 30/09/2026</span><h2 id="terms-title">Términos de uso y privacidad</h2><p>CyberCript es un laboratorio educativo creado por Brayan Fernando Arango Córdoba.</p><h3>Aprender con responsabilidad</h3><p>Utiliza ejemplos ficticios. No introduzcas contraseñas reales ni datos privados en las prácticas. No uses lo aprendido para acceder a cuentas o sistemas sin permiso.</p><h3>Modo invitado</h3><p>Las respuestas solo permanecen en la memoria de esta página. No se guardan en el navegador ni en la nube y se pierden al recargar, salir o cerrar la página. Puedes descargar voluntariamente un informe de la sesión.</p><h3>Con una cuenta</h3><p>Firebase Authentication gestiona el correo, la contraseña de acceso y el nombre visible opcional. El progreso incluye el módulo y la etapa visitada para poder retomarlos. Tras verificar el correo, se guarda en Firestore y en una copia local asociada a la cuenta. Cierra sesión en equipos compartidos.</p><h3>Contenido educativo</h3><p>Las prácticas son simulaciones y sus valoraciones son orientativas. Las fuentes externas tienen sus propias condiciones. Los informes solo se descargan cuando lo solicitas.</p><form method="dialog"><button class="btn">Volver al acceso</button></form></dialog>`;}
 function view(){
  const configured=CyberAccount.configured,known=CyberAccount.user;
  return `<main class="entry-page" id="access-main"><section class="entry-story"><a class="brand" href="#inicio" aria-label="CyberCript"><img src="./favicon.svg" class="brand-icon" alt=""><span>cyber<span class="lime-text">cript</span><small>LABORATORIO VIRTUAL</small></span></a><div class="entry-story-copy"><span class="entry-kicker"><i></i> TU PRÓXIMO DESCUBRIMIENTO</span><h1>Un pequeño paso.<br><span>Más seguridad.</span></h1><p>Aprende a proteger tu mundo digital, una idea y un reto a la vez.</p><div class="entry-orbit" aria-hidden="true"><div class="orbit-ring"></div><div class="orbit-ring inner"></div><div class="orbit-core">CC</div><span class="orbit-node one">⌘</span><span class="orbit-node two">↗</span><span class="orbit-node three">◎</span></div></div><span class="entry-signature">© 2026 Brayan Fernando Arango Córdoba.<br>Todos los derechos reservados.</span></section><section class="entry-access"><div class="access-card"><span class="eyebrow">BIENVENIDO A CYBERCRIPT</span><h2 tabindex="-1" id="access-title">${known?'Continúa aprendiendo.':mode==='register'?'Crea tu espacio.':mode==='recover'?'Recupera tu acceso.':'Tu aprendizaje empieza aquí.'}</h2><p class="muted">${known?'Tu cuenta está lista para continuar.':'Entra con tu cuenta o explora como invitado.'}</p>${known?`<div class="known-account"><b>${esc(known.displayName||'Mi cuenta')}</b><span>${esc(known.email)}</span></div>`:`<div class="account-tabs" role="group" aria-label="Opciones de acceso"><button data-entry-mode="login" aria-pressed="${mode==='login'}">Iniciar sesión</button><button data-entry-mode="register" aria-pressed="${mode==='register'}">Crear cuenta</button></div><form id="entry-form"><label for="entry-email">Correo electrónico</label><input id="entry-email" type="email" autocomplete="email" placeholder="tu@correo.com" aria-describedby="access-status" required ${configured?'':'disabled'}>${mode==='recover'?'':`<label for="entry-password">Contraseña</label>${CyberUI.passwordField('entry-password',`autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="${mode==='register'?12:6}" placeholder="${mode==='register'?'Al menos 12 caracteres':'Tu contraseña'}" aria-describedby="access-status" required ${configured?'':'disabled'}`)}`}${mode==='register'?`<label for="entry-confirm">Confirmar contraseña</label>${CyberUI.passwordField('entry-confirm',`autocomplete="new-password" minlength="12" aria-describedby="access-status" required ${configured?'':'disabled'}`,'confirmación de contraseña')}`:''}</form>${mode==='login'?'<button class="text-button recovery-link" data-entry-mode="recover">¿Olvidaste tu contraseña?</button>':''}`}
   <label class="terms-check"><input type="checkbox" id="entry-terms" ${accepted?'checked':''}><span>Acepto los <button class="text-button" type="button" id="open-terms">términos de uso y privacidad</button>.</span></label><p class="access-status" id="access-status" role="status" aria-live="polite"></p>
   <button class="btn access-primary" id="entry-submit" ${accepted&&!restoring&&!authBusy&&(configured||known)?'':'disabled'}>${known?'Continuar con mi cuenta':mode==='register'?'Crear mi cuenta':mode==='recover'?'Enviar enlace de recuperación':'Iniciar sesión'} <span aria-hidden="true">→</span></button>
   ${!configured?'<p class="setup-note">El acceso con cuenta estará disponible pronto. Ya puedes explorar como invitado.</p>':''}
   <div class="access-divider"><span>O EXPLORA A TU RITMO</span></div><button class="btn guest-button" id="entry-guest" ${accepted&&!restoring&&!authBusy?'':'disabled'}>Entrar como invitado <span aria-hidden="true">↗</span></button><p class="guest-note">Sin registro. Tu progreso se pierde al recargar o salir.</p>${known?'<button class="text-button" id="entry-logout">Usar otra cuenta</button>':''}</div><small class="access-footer">7 módulos · Retos cortos · A tu ritmo</small></section></main>${terms()}`;
 }
 function draw(){
  const root=document.querySelector('#entry-root');root.innerHTML=view();
  root.querySelectorAll('[data-entry-mode]').forEach(b=>b.onclick=()=>{if(authBusy)return;mode=b.dataset.entryMode;draw();document.querySelector('#access-title').focus();});
  document.querySelector('#open-terms').onclick=()=>document.querySelector('#terms-dialog').showModal();
  document.querySelector('#entry-terms').onchange=e=>{accepted=e.target.checked;document.querySelector('#entry-guest').disabled=!accepted||restoring||authBusy;document.querySelector('#entry-submit').disabled=!accepted||restoring||authBusy||(!CyberAccount.configured&&!CyberAccount.user);};
  document.querySelector('#entry-guest').onclick=()=>{if(!accepted||restoring||authBusy)return;if(CyberAccount.user)CyberAccount.logout();enter(true);};
  const submit=async e=>{
   e?.preventDefault();if(!accepted||restoring||authBusy)return;
   if(CyberAccount.user){enter(false);return;}if(!CyberAccount.configured)return;
   const form=document.querySelector('#entry-form');if(!form.reportValidity())return;
   const email=document.querySelector('#entry-email').value.trim(),pass=document.querySelector('#entry-password')?.value||'';
   if(mode==='register'&&pass!==document.querySelector('#entry-confirm').value){document.querySelector('#access-status').textContent='Las contraseñas no coinciden.';document.querySelector('#entry-confirm').setAttribute('aria-invalid','true');document.querySelector('#entry-confirm').focus();return;}
   authBusy=true;const submitButton=document.querySelector('#entry-submit'),guestButton=document.querySelector('#entry-guest'),originalLabel=submitButton.innerHTML;submitButton.disabled=true;guestButton.disabled=true;submitButton.setAttribute('aria-busy','true');submitButton.innerHTML=`<span class="button-spinner" aria-hidden="true"></span> ${mode==='register'?'Creando tu cuenta…':mode==='recover'?'Enviando instrucciones…':'Comprobando tu acceso…'}`;document.querySelector('#access-status').textContent='';
   try{await CyberAccount.authenticate(mode,email,pass);if(mode==='recover'){document.querySelector('#access-status').classList.add('is-success');document.querySelector('#access-status').textContent='Si existe una cuenta con ese correo, recibirás un enlace de recuperación. Revisa también la carpeta de spam.';}else enter(false);}
   catch(error){const message=document.querySelector('#access-status');message.classList.remove('is-success');message.setAttribute('role','alert');message.textContent=error.message;if(error.message.includes('correo y la contraseña')){document.querySelector('#entry-email')?.setAttribute('aria-invalid','true');document.querySelector('#entry-password')?.setAttribute('aria-invalid','true');}}
   finally{authBusy=false;const currentSubmit=document.querySelector('#entry-submit'),currentGuest=document.querySelector('#entry-guest');if(currentSubmit){currentSubmit.disabled=!accepted||(!CyberAccount.configured&&!CyberAccount.user);currentSubmit.removeAttribute('aria-busy');currentSubmit.innerHTML=originalLabel;}if(currentGuest)currentGuest.disabled=!accepted;}
  };
  document.querySelector('#entry-submit').onclick=submit;
  const form=document.querySelector('#entry-form');if(form){form.onsubmit=submit;form.addEventListener('input',()=>{form.querySelectorAll('[aria-invalid]').forEach(field=>field.removeAttribute('aria-invalid'));const message=document.querySelector('#access-status');message.textContent='';message.setAttribute('role','status');});}
  const logout=document.querySelector('#entry-logout');if(logout)logout.onclick=()=>CyberAccount.logout();
 }
 function enter(asGuest){document.querySelector('.skip').href='#main';allowed=true;guest=asGuest;if(asGuest){state=fresh();quiz=null;memoryOnly=true;}else memoryOnly=false;document.querySelector('#entry-root').hidden=true;document.querySelector('.app').hidden=false;document.querySelector('.app').inert=false;document.body.classList.remove('access-open');document.querySelector('#account-shortcut-label').textContent=asGuest?'Invitado · No se guarda':'Mi cuenta';location.hash='inicio';render();document.querySelector('#main').focus();}
 function show(){CyberUI.closeMobileMenu(false);document.body.classList.remove('home-active','learning-active');document.querySelector('.skip').href='#access-title';allowed=false;guest=false;accepted=false;document.querySelector('.app').hidden=true;document.querySelector('.app').inert=true;document.querySelector('#entry-root').hidden=false;document.body.classList.add('access-open');draw();}
 function start(){show();const splash=document.querySelector('#splash');const finish=()=>{if(!loading)return;loading=false;splash.classList.add('splash-exit');document.querySelector('#entry-root').inert=false;setTimeout(()=>{splash.hidden=true;document.querySelector('#access-title')?.focus({preventScroll:true});},250);};document.querySelector('#skip-intro').onclick=finish;setTimeout(finish,matchMedia('(prefers-reduced-motion: reduce)').matches?0:1800);CyberAccount.restore().finally(()=>{restoring=false;if(!allowed)draw();});}
 window.addEventListener('pagehide',()=>{if(guest){state=fresh();quiz=null;allowed=false;guest=false;}});
 window.addEventListener('pageshow',e=>{if(e.persisted&&!allowed){show();render();}});
 return {start,show,draw,get allowed(){return allowed},get guest(){return guest}};
})();
